`Object.values(statuses)` is called twice — once to build `changeValues` and again to build `testValues`. A single pass with `reduce` (or `forEach`) would halve the iteration and make the partitioning intent clearer:
```ts
const { changeValues, testValues } = Object.values(statuses).reduce(
  (acc, status) => {
    if (status.typeId === CHANGE_DETECTION_TYPE_ID) {
      acc.changeValues.push(status.value);
    } else {
      acc.testValues.push(status.value);
    }
    return acc;
  },
  { changeValues: [] as StatusValue[], testValues: [] as StatusValue[] }
);
```
